{"i":768,"type":"thought","stage":"vote","round":1,"phase":"campaign","name":"Fenn","text":"Cole is a rival. Voting for him protects Ash, whom I owe my life to."}
{"i":770,"type":"whisper","stage":"vote","round":1,"phase":"campaign","from":"Fenn","to":"Ash","text":"Target Cole."}
{"i":771,"type":"thought","stage":"vote","round":1,"phase":"campaign","name":"Hana","text":"Cole saved me on the step and has a pact with Fenn who wants Cole gone. If Fenn succeeds, I lose my shield and protector. Better to keep Cole alive for now and let Ash be the target; I owe Gus's lever save to no one alive."}
{"i":773,"type":"whisper","stage":"vote","round":1,"phase":"campaign","from":"Hana","to":"Cole","text":"Fenn is targeting you. Vote Ash with me."}
